-- receiving/summary
INSERT INTO public.pff_player_gamelogs (pid, esbid, season_year, pff_game_id, pff_player_id, pff_team_id, nfl_team, player_position, grade_offense, grade_offense_penalty, grade_defense, grade_defense_penalty, grade_pass, grade_run, grade_pass_block, grade_run_block, grade_pass_route, grade_hands_drop, grade_hands_fumble, grade_coverage_defense, grade_pass_rush_defense, grade_run_defense, grade_tackle, grade_punter, penalties, declined_penalties, routes, yards_per_route_run, scrambles, receiving_targets, receiving_receptions, receiving_yards, receiving_touchdowns, receiving_first_downs, receiving_longest, receiving_drops, receiving_drop_rate, receiving_fumbles, receiving_interceptions, receiving_caught_percentage, receiving_contested_targets, receiving_contested_receptions, receiving_contested_catch_rate, receiving_avoided_tackles, receiving_yards_after_catch, receiving_yards_after_catch_per_reception, receiving_yards_per_reception, receiving_average_depth_of_target, receiving_targeted_quarterback_rating, receiving_pass_plays, receiving_pass_blocks, receiving_pass_block_rate, receiving_route_rate, receiving_inline_snaps, receiving_inline_rate, receiving_slot_snaps, receiving_slot_rate, receiving_wide_snaps, receiving_wide_rate)
SELECT g.pid, g.esbid, ng.season_year, g.pff_game_id, g.pff_player_id, g.pff_team_id, g.nfl_team, g.player_position,
  CASE WHEN g.facet_payload->>'grades_offense' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_offense')::numeric END::numeric(4,1) AS grade_offense,
  CASE WHEN g.facet_payload->>'grades_offense_penalty' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_offense_penalty')::numeric END::numeric(4,1) AS grade_offense_penalty,
