  CASE WHEN g.facet_payload->>'scrambles' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'scrambles')::numeric END::smallint AS scrambles,
  CASE WHEN g.facet_payload->>'targets' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'targets')::numeric END::smallint AS receiving_targets,
