  CASE WHEN g.facet_payload->>'contested_targets' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'contested_targets')::numeric END::smallint AS receiving_contested_targets,
  CASE WHEN g.facet_payload->>'contested_receptions' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'contested_receptions')::numeric END::smallint AS receiving_contested_receptions,
  CASE WHEN g.facet_payload->>'contested_catch_rate' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'contested_catch_rate')::numeric END::numeric(4,1) AS receiving_contested_catch_rate,
  CASE WHEN g.facet_payload->>'avoided_tackles' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'avoided_tackles')::numeric END::smallint AS receiving_avoided_tackles,
  CASE WHEN g.facet_payload->>'yards_after_catch' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'yards_after_catch')::numeric END::smallint AS receiving_yards_after_catch,
  CASE WHEN g.facet_payload->>'yards_after_catch_per_reception' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'yards_after_catch_per_reception')::numeric END::numeric(4,1) AS receiving_yards_after_catch_per_reception,
  CASE WHEN g.facet_payload->>'yards_per_reception' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'yards_per_reception')::numeric END::numeric(4,1) AS receiving_yards_per_reception,
  CASE WHEN g.facet_payload->>'avg_depth_of_target' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'avg_depth_of_target')::numeric END::numeric(4,1) AS receiving_average_depth_of_target,
  CASE WHEN g.facet_payload->>'targeted_qb_rating' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'targeted_qb_rating')::numeric END::numeric(4,1) AS receiving_targeted_quarterback_rating,
  CASE WHEN g.facet_payload->>'pass_plays' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'pass_plays')::numeric END::smallint AS receiving_pass_plays,
