  CASE WHEN g.facet_payload->>'route_rate' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'route_rate')::numeric END::numeric(4,1) AS receiving_route_rate,
  CASE WHEN g.facet_payload->>'inline_snaps' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'inline_snaps')::numeric END::smallint AS receiving_inline_snaps,
