  CASE WHEN g.facet_payload->>'snap_counts_coverage' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_coverage')::numeric END::smallint AS defense_snaps_coverage,
  CASE WHEN g.facet_payload->>'snap_counts_dl' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_dl')::numeric END::smallint AS defense_snaps_defensive_line,
  CASE WHEN g.facet_payload->>'snap_counts_dl_a_gap' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_dl_a_gap')::numeric END::smallint AS defense_snaps_center_guard_gap,
  CASE WHEN g.facet_payload->>'snap_counts_dl_b_gap' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_dl_b_gap')::numeric END::smallint AS defense_snaps_guard_tackle_gap,
  CASE WHEN g.facet_payload->>'snap_counts_dl_outside_t' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_dl_outside_t')::numeric END::smallint AS defense_snaps_defensive_line_outside_tackle,
  CASE WHEN g.facet_payload->>'snap_counts_dl_over_t' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_dl_over_t')::numeric END::smallint AS defense_snaps_defensive_line_over_tackle,
  CASE WHEN g.facet_payload->>'snap_counts_fs' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_fs')::numeric END::smallint AS defense_snaps_free_safety,
  CASE WHEN g.facet_payload->>'snap_counts_offball' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_offball')::numeric END::smallint AS defense_snaps_second_level,
  CASE WHEN g.facet_payload->>'snap_counts_pass_rush' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_pass_rush')::numeric END::smallint AS defense_snaps_pass_rush,
  CASE WHEN g.facet_payload->>'snap_counts_run_defense' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_run_defense')::numeric END::smallint AS defense_snaps_run_defense,
  CASE WHEN g.facet_payload->>'snap_counts_slot' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snap_counts_slot')::numeric END::smallint AS defense_snaps_slot,
  CASE WHEN g.facet_payload->>'tackles' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'tackles')::numeric END::smallint AS defense_tackles,
  CASE WHEN g.facet_payload->>'assists' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'assists')::numeric END::smallint AS defense_assists,
  CASE WHEN g.facet_payload->>'missed_tackles' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'missed_tackles')::numeric END::smallint AS defense_missed_tackles,
  CASE WHEN g.facet_payload->>'missed_tackle_rate' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'missed_tackle_rate')::numeric END::numeric(4,1) AS defense_missed_tackle_rate,
  CASE WHEN g.facet_payload->>'tackles_for_loss' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'tackles_for_loss')::numeric END::smallint AS defense_tackles_for_loss,
  CASE WHEN g.facet_payload->>'stops' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'stops')::numeric END::smallint AS defense_stops,
  CASE WHEN g.facet_payload->>'sacks' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'sacks')::numeric END::smallint AS defense_sacks,
  CASE WHEN g.facet_payload->>'hits' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'hits')::numeric END::smallint AS defense_hits,
  CASE WHEN g.facet_payload->>'hurries' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'hurries')::numeric END::smallint AS defense_hurries,
  CASE WHEN g.facet_payload->>'total_pressures' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'total_pressures')::numeric END::smallint AS defense_total_pressures,
  CASE WHEN g.facet_payload->>'batted_passes' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'batted_passes')::numeric END::smallint AS defense_batted_passes,
  CASE WHEN g.facet_payload->>'pass_break_ups' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'pass_break_ups')::numeric END::smallint AS defense_pass_breakups,
  CASE WHEN g.facet_payload->>'interceptions' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'interceptions')::numeric END::smallint AS defense_interceptions,
  CASE WHEN g.facet_payload->>'interception_touchdowns' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'interception_touchdowns')::numeric END::smallint AS defense_interception_touchdowns,
  CASE WHEN g.facet_payload->>'forced_fumbles' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'forced_fumbles')::numeric END::smallint AS defense_forced_fumbles,
  CASE WHEN g.facet_payload->>'fumble_recoveries' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'fumble_recoveries')::numeric END::smallint AS defense_fumble_recoveries,
  CASE WHEN g.facet_payload->>'fumble_recovery_touchdowns' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'fumble_recovery_touchdowns')::numeric END::smallint AS defense_fumble_recovery_touchdowns,
  CASE WHEN g.facet_payload->>'safeties' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'safeties')::numeric END::smallint AS defense_safeties,
  CASE WHEN g.facet_payload->>'targets' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'targets')::numeric END::smallint AS defense_targets_allowed,
  CASE WHEN g.facet_payload->>'receptions' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'receptions')::numeric END::smallint AS defense_receptions_allowed,
  CASE WHEN g.facet_payload->>'yards' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'yards')::numeric END::smallint AS defense_yards_allowed,
  CASE WHEN g.facet_payload->>'touchdowns' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'touchdowns')::numeric END::smallint AS defense_touchdowns_allowed,
  CASE WHEN g.facet_payload->>'yards_after_catch' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'yards_after_catch')::numeric END::smallint AS defense_yards_after_catch_allowed,
  CASE WHEN g.facet_payload->>'yards_per_reception' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'yards_per_reception')::numeric END::numeric(4,1) AS defense_yards_per_reception_allowed,
  CASE WHEN g.facet_payload->>'longest' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'longest')::numeric END::smallint AS defense_longest_reception_allowed,
  CASE WHEN g.facet_payload->>'catch_rate' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'catch_rate')::numeric END::numeric(4,1) AS defense_catch_rate_allowed,
  CASE WHEN g.facet_payload->>'qb_rating_against' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'qb_rating_against')::numeric END::numeric(4,1) AS defense_quarterback_rating_against
FROM public.pff_player_facet_gamelogs g
JOIN public.nfl_games ng ON ng.esbid::text = g.esbid::text
WHERE g.facet = 'defense/summary'
ON CONFLICT (pid, esbid) DO UPDATE SET
  grade_offense = COALESCE(EXCLUDED.grade_offense, pff_player_gamelogs.grade_offense),
  grade_offense_penalty = COALESCE(EXCLUDED.grade_offense_penalty, pff_player_gamelogs.grade_offense_penalty),
  grade_defense = COALESCE(EXCLUDED.grade_defense, pff_player_gamelogs.grade_defense),
  grade_defense_penalty = COALESCE(EXCLUDED.grade_defense_penalty, pff_player_gamelogs.grade_defense_penalty),
  grade_pass = COALESCE(EXCLUDED.grade_pass, pff_player_gamelogs.grade_pass),
  grade_run = COALESCE(EXCLUDED.grade_run, pff_player_gamelogs.grade_run),
  grade_pass_block = COALESCE(EXCLUDED.grade_pass_block, pff_player_gamelogs.grade_pass_block),
  grade_run_block = COALESCE(EXCLUDED.grade_run_block, pff_player_gamelogs.grade_run_block),
  grade_pass_route = COALESCE(EXCLUDED.grade_pass_route, pff_player_gamelogs.grade_pass_route),
  grade_hands_drop = COALESCE(EXCLUDED.grade_hands_drop, pff_player_gamelogs.grade_hands_drop),
  grade_hands_fumble = COALESCE(EXCLUDED.grade_hands_fumble, pff_player_gamelogs.grade_hands_fumble),
  grade_coverage_defense = COALESCE(EXCLUDED.grade_coverage_defense, pff_player_gamelogs.grade_coverage_defense),
  grade_pass_rush_defense = COALESCE(EXCLUDED.grade_pass_rush_defense, pff_player_gamelogs.grade_pass_rush_defense),
  grade_run_defense = COALESCE(EXCLUDED.grade_run_defense, pff_player_gamelogs.grade_run_defense),
  grade_tackle = COALESCE(EXCLUDED.grade_tackle, pff_player_gamelogs.grade_tackle),
  grade_punter = COALESCE(EXCLUDED.grade_punter, pff_player_gamelogs.grade_punter),
  penalties = COALESCE(EXCLUDED.penalties, pff_player_gamelogs.penalties),
  declined_penalties = COALESCE(EXCLUDED.declined_penalties, pff_player_gamelogs.declined_penalties),
  routes = COALESCE(EXCLUDED.routes, pff_player_gamelogs.routes),
  yards_per_route_run = COALESCE(EXCLUDED.yards_per_route_run, pff_player_gamelogs.yards_per_route_run),
  scrambles = COALESCE(EXCLUDED.scrambles, pff_player_gamelogs.scrambles),
  defense_snaps = COALESCE(EXCLUDED.defense_snaps, pff_player_gamelogs.defense_snaps),
  defense_snaps_box = COALESCE(EXCLUDED.defense_snaps_box, pff_player_gamelogs.defense_snaps_box),
  defense_snaps_corner = COALESCE(EXCLUDED.defense_snaps_corner, pff_player_gamelogs.defense_snaps_corner),
  defense_snaps_coverage = COALESCE(EXCLUDED.defense_snaps_coverage, pff_player_gamelogs.defense_snaps_coverage),
  defense_snaps_defensive_line = COALESCE(EXCLUDED.defense_snaps_defensive_line, pff_player_gamelogs.defense_snaps_defensive_line),
  defense_snaps_center_guard_gap = COALESCE(EXCLUDED.defense_snaps_center_guard_gap, pff_player_gamelogs.defense_snaps_center_guard_gap),
  defense_snaps_guard_tackle_gap = COALESCE(EXCLUDED.defense_snaps_guard_tackle_gap, pff_player_gamelogs.defense_snaps_guard_tackle_gap),
  defense_snaps_defensive_line_outside_tackle = COALESCE(EXCLUDED.defense_snaps_defensive_line_outside_tackle, pff_player_gamelogs.defense_snaps_defensive_line_outside_tackle),
  defense_snaps_defensive_line_over_tackle = COALESCE(EXCLUDED.defense_snaps_defensive_line_over_tackle, pff_player_gamelogs.defense_snaps_defensive_line_over_tackle),
  defense_snaps_free_safety = COALESCE(EXCLUDED.defense_snaps_free_safety, pff_player_gamelogs.defense_snaps_free_safety),
  defense_snaps_second_level = COALESCE(EXCLUDED.defense_snaps_second_level, pff_player_gamelogs.defense_snaps_second_level),
  defense_snaps_pass_rush = COALESCE(EXCLUDED.defense_snaps_pass_rush, pff_player_gamelogs.defense_snaps_pass_rush),
  defense_snaps_run_defense = COALESCE(EXCLUDED.defense_snaps_run_defense, pff_player_gamelogs.defense_snaps_run_defense),
  defense_snaps_slot = COALESCE(EXCLUDED.defense_snaps_slot, pff_player_gamelogs.defense_snaps_slot),
  defense_tackles = COALESCE(EXCLUDED.defense_tackles, pff_player_gamelogs.defense_tackles),
  defense_assists = COALESCE(EXCLUDED.defense_assists, pff_player_gamelogs.defense_assists),
  defense_missed_tackles = COALESCE(EXCLUDED.defense_missed_tackles, pff_player_gamelogs.defense_missed_tackles),
  defense_missed_tackle_rate = COALESCE(EXCLUDED.defense_missed_tackle_rate, pff_player_gamelogs.defense_missed_tackle_rate),
  defense_tackles_for_loss = COALESCE(EXCLUDED.defense_tackles_for_loss, pff_player_gamelogs.defense_tackles_for_loss),
  defense_stops = COALESCE(EXCLUDED.defense_stops, pff_player_gamelogs.defense_stops),
  defense_sacks = COALESCE(EXCLUDED.defense_sacks, pff_player_gamelogs.defense_sacks),
  defense_hits = COALESCE(EXCLUDED.defense_hits, pff_player_gamelogs.defense_hits),
  defense_hurries = COALESCE(EXCLUDED.defense_hurries, pff_player_gamelogs.defense_hurries),
  defense_total_pressures = COALESCE(EXCLUDED.defense_total_pressures, pff_player_gamelogs.defense_total_pressures),
  defense_batted_passes = COALESCE(EXCLUDED.defense_batted_passes, pff_player_gamelogs.defense_batted_passes),
  defense_pass_breakups = COALESCE(EXCLUDED.defense_pass_breakups, pff_player_gamelogs.defense_pass_breakups),
  defense_interceptions = COALESCE(EXCLUDED.defense_interceptions, pff_player_gamelogs.defense_interceptions),
  defense_interception_touchdowns = COALESCE(EXCLUDED.defense_interception_touchdowns, pff_player_gamelogs.defense_interception_touchdowns),
  defense_forced_fumbles = COALESCE(EXCLUDED.defense_forced_fumbles, pff_player_gamelogs.defense_forced_fumbles),
  defense_fumble_recoveries = COALESCE(EXCLUDED.defense_fumble_recoveries, pff_player_gamelogs.defense_fumble_recoveries),
  defense_fumble_recovery_touchdowns = COALESCE(EXCLUDED.defense_fumble_recovery_touchdowns, pff_player_gamelogs.defense_fumble_recovery_touchdowns),
  defense_safeties = COALESCE(EXCLUDED.defense_safeties, pff_player_gamelogs.defense_safeties),
  defense_targets_allowed = COALESCE(EXCLUDED.defense_targets_allowed, pff_player_gamelogs.defense_targets_allowed),
  defense_receptions_allowed = COALESCE(EXCLUDED.defense_receptions_allowed, pff_player_gamelogs.defense_receptions_allowed),
  defense_yards_allowed = COALESCE(EXCLUDED.defense_yards_allowed, pff_player_gamelogs.defense_yards_allowed),
  defense_touchdowns_allowed = COALESCE(EXCLUDED.defense_touchdowns_allowed, pff_player_gamelogs.defense_touchdowns_allowed),
  defense_yards_after_catch_allowed = COALESCE(EXCLUDED.defense_yards_after_catch_allowed, pff_player_gamelogs.defense_yards_after_catch_allowed),
