-- punting/summary
INSERT INTO public.pff_player_gamelogs (pid, esbid, season_year, pff_game_id, pff_player_id, pff_team_id, nfl_team, player_position, grade_offense, grade_offense_penalty, grade_defense, grade_defense_penalty, grade_pass, grade_run, grade_pass_block, grade_run_block, grade_pass_route, grade_hands_drop, grade_hands_fumble, grade_coverage_defense, grade_pass_rush_defense, grade_run_defense, grade_tackle, grade_punter, penalties, declined_penalties, routes, yards_per_route_run, scrambles, punting_snaps, punting_attempts, punting_yards, punting_blocks, punting_touchbacks, punting_inside_twenty_yard_line, punting_downed, punting_out_of_bounds, punting_fair_catches, punting_returns, punting_return_yards, punting_longest_punt, punting_total_net_yards, punting_average_net_yards, punting_average_yards_per_attempt, punting_average_yards_per_return, punting_percentage_returned, punting_attempts_with_hangtime, punting_total_hangtime, punting_average_hangtime)
SELECT g.pid, g.esbid, ng.season_year, g.pff_game_id, g.pff_player_id, g.pff_team_id, g.nfl_team, g.player_position,
  CASE WHEN g.facet_payload->>'grades_offense' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_offense')::numeric END::numeric(4,1) AS grade_offense,
  CASE WHEN g.facet_payload->>'grades_offense_penalty' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_offense_penalty')::numeric END::numeric(4,1) AS grade_offense_penalty,
  CASE WHEN g.facet_payload->>'grades_defense' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_defense')::numeric END::numeric(4,1) AS grade_defense,
  CASE WHEN g.facet_payload->>'grades_defense_penalty' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_defense_penalty')::numeric END::numeric(4,1) AS grade_defense_penalty,
  CASE WHEN g.facet_payload->>'grades_pass' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_pass')::numeric END::numeric(4,1) AS grade_pass,
  CASE WHEN g.facet_payload->>'grades_run' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_run')::numeric END::numeric(4,1) AS grade_run,
  CASE WHEN g.facet_payload->>'grades_pass_block' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_pass_block')::numeric END::numeric(4,1) AS grade_pass_block,
  CASE WHEN g.facet_payload->>'grades_run_block' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_run_block')::numeric END::numeric(4,1) AS grade_run_block,
  CASE WHEN g.facet_payload->>'grades_pass_route' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_pass_route')::numeric END::numeric(4,1) AS grade_pass_route,
  CASE WHEN g.facet_payload->>'grades_hands_drop' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_hands_drop')::numeric END::numeric(4,1) AS grade_hands_drop,
  CASE WHEN g.facet_payload->>'grades_hands_fumble' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_hands_fumble')::numeric END::numeric(4,1) AS grade_hands_fumble,
  CASE WHEN g.facet_payload->>'grades_coverage_defense' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_coverage_defense')::numeric END::numeric(4,1) AS grade_coverage_defense,
  CASE WHEN g.facet_payload->>'grades_pass_rush_defense' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_pass_rush_defense')::numeric END::numeric(4,1) AS grade_pass_rush_defense,
  CASE WHEN g.facet_payload->>'grades_run_defense' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_run_defense')::numeric END::numeric(4,1) AS grade_run_defense,
  CASE WHEN g.facet_payload->>'grades_tackle' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_tackle')::numeric END::numeric(4,1) AS grade_tackle,
  CASE WHEN g.facet_payload->>'grades_punter' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'grades_punter')::numeric END::numeric(4,1) AS grade_punter,
  CASE WHEN g.facet_payload->>'penalties' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'penalties')::numeric END::smallint AS penalties,
  CASE WHEN g.facet_payload->>'declined_penalties' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'declined_penalties')::numeric END::smallint AS declined_penalties,
  CASE WHEN g.facet_payload->>'routes' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'routes')::numeric END::smallint AS routes,
  CASE WHEN g.facet_payload->>'yprr' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'yprr')::numeric END::numeric(5,2) AS yards_per_route_run,
  CASE WHEN g.facet_payload->>'scrambles' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'scrambles')::numeric END::smallint AS scrambles,
  CASE WHEN g.facet_payload->>'snaps' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'snaps')::numeric END::smallint AS punting_snaps,
  CASE WHEN g.facet_payload->>'attempts' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'attempts')::numeric END::smallint AS punting_attempts,
  CASE WHEN g.facet_payload->>'yards' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'yards')::numeric END::smallint AS punting_yards,
  CASE WHEN g.facet_payload->>'blocks' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'blocks')::numeric END::smallint AS punting_blocks,
  CASE WHEN g.facet_payload->>'touchbacks' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'touchbacks')::numeric END::smallint AS punting_touchbacks,
  CASE WHEN g.facet_payload->>'inside_twenties' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'inside_twenties')::numeric END::smallint AS punting_inside_twenty_yard_line,
  CASE WHEN g.facet_payload->>'downeds' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'downeds')::numeric END::smallint AS punting_downed,
  CASE WHEN g.facet_payload->>'out_of_bounds' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'out_of_bounds')::numeric END::smallint AS punting_out_of_bounds,
  CASE WHEN g.facet_payload->>'fair_catches' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'fair_catches')::numeric END::smallint AS punting_fair_catches,
  CASE WHEN g.facet_payload->>'returns' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'returns')::numeric END::smallint AS punting_returns,
  CASE WHEN g.facet_payload->>'return_yards' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'return_yards')::numeric END::smallint AS punting_return_yards,
  CASE WHEN g.facet_payload->>'long' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'long')::numeric END::smallint AS punting_longest_punt,
  CASE WHEN g.facet_payload->>'total_net_yards' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'total_net_yards')::numeric END::smallint AS punting_total_net_yards,
  CASE WHEN g.facet_payload->>'average_net_yards' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'average_net_yards')::numeric END::numeric(5,2) AS punting_average_net_yards,
  CASE WHEN g.facet_payload->>'average_yards_per_attempt' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'average_yards_per_attempt')::numeric END::numeric(5,2) AS punting_average_yards_per_attempt,
  CASE WHEN g.facet_payload->>'average_yards_per_return' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'average_yards_per_return')::numeric END::numeric(4,1) AS punting_average_yards_per_return,
  CASE WHEN g.facet_payload->>'percent_returned' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'percent_returned')::numeric END::numeric(4,1) AS punting_percentage_returned,
  CASE WHEN g.facet_payload->>'attempts_with_hangtime' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'attempts_with_hangtime')::numeric END::smallint AS punting_attempts_with_hangtime,
  CASE WHEN g.facet_payload->>'total_hangtime' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'total_hangtime')::numeric END::numeric(5,2) AS punting_total_hangtime,
  CASE WHEN g.facet_payload->>'average_hangtime' ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (g.facet_payload->>'average_hangtime')::numeric END::numeric(4,2) AS punting_average_hangtime
FROM public.pff_player_facet_gamelogs g
JOIN public.nfl_games ng ON ng.esbid::text = g.esbid::text
WHERE g.facet = 'punting/summary'
ON CONFLICT (pid, esbid) DO UPDATE SET
  grade_offense = COALESCE(EXCLUDED.grade_offense, pff_player_gamelogs.grade_offense),
  grade_offense_penalty = COALESCE(EXCLUDED.grade_offense_penalty, pff_player_gamelogs.grade_offense_penalty),
  grade_defense = COALESCE(EXCLUDED.grade_defense, pff_player_gamelogs.grade_defense),
  grade_defense_penalty = COALESCE(EXCLUDED.grade_defense_penalty, pff_player_gamelogs.grade_defense_penalty),
  grade_pass = COALESCE(EXCLUDED.grade_pass, pff_player_gamelogs.grade_pass),
  grade_run = COALESCE(EXCLUDED.grade_run, pff_player_gamelogs.grade_run),
  grade_pass_block = COALESCE(EXCLUDED.grade_pass_block, pff_player_gamelogs.grade_pass_block),
  grade_run_block = COALESCE(EXCLUDED.grade_run_block, pff_player_gamelogs.grade_run_block),
  grade_pass_route = COALESCE(EXCLUDED.grade_pass_route, pff_player_gamelogs.grade_pass_route),
  grade_hands_drop = COALESCE(EXCLUDED.grade_hands_drop, pff_player_gamelogs.grade_hands_drop),
  grade_hands_fumble = COALESCE(EXCLUDED.grade_hands_fumble, pff_player_gamelogs.grade_hands_fumble),
  grade_coverage_defense = COALESCE(EXCLUDED.grade_coverage_defense, pff_player_gamelogs.grade_coverage_defense),
  grade_pass_rush_defense = COALESCE(EXCLUDED.grade_pass_rush_defense, pff_player_gamelogs.grade_pass_rush_defense),
  grade_run_defense = COALESCE(EXCLUDED.grade_run_defense, pff_player_gamelogs.grade_run_defense),
  grade_tackle = COALESCE(EXCLUDED.grade_tackle, pff_player_gamelogs.grade_tackle),
  grade_punter = COALESCE(EXCLUDED.grade_punter, pff_player_gamelogs.grade_punter),
  penalties = COALESCE(EXCLUDED.penalties, pff_player_gamelogs.penalties),
  declined_penalties = COALESCE(EXCLUDED.declined_penalties, pff_player_gamelogs.declined_penalties),
  routes = COALESCE(EXCLUDED.routes, pff_player_gamelogs.routes),
  yards_per_route_run = COALESCE(EXCLUDED.yards_per_route_run, pff_player_gamelogs.yards_per_route_run),
  scrambles = COALESCE(EXCLUDED.scrambles, pff_player_gamelogs.scrambles),
  punting_snaps = COALESCE(EXCLUDED.punting_snaps, pff_player_gamelogs.punting_snaps),
  punting_attempts = COALESCE(EXCLUDED.punting_attempts, pff_player_gamelogs.punting_attempts),
  punting_yards = COALESCE(EXCLUDED.punting_yards, pff_player_gamelogs.punting_yards),
  punting_blocks = COALESCE(EXCLUDED.punting_blocks, pff_player_gamelogs.punting_blocks),
  punting_touchbacks = COALESCE(EXCLUDED.punting_touchbacks, pff_player_gamelogs.punting_touchbacks),
  punting_inside_twenty_yard_line = COALESCE(EXCLUDED.punting_inside_twenty_yard_line, pff_player_gamelogs.punting_inside_twenty_yard_line),
  punting_downed = COALESCE(EXCLUDED.punting_downed, pff_player_gamelogs.punting_downed),
  punting_out_of_bounds = COALESCE(EXCLUDED.punting_out_of_bounds, pff_player_gamelogs.punting_out_of_bounds),
  punting_fair_catches = COALESCE(EXCLUDED.punting_fair_catches, pff_player_gamelogs.punting_fair_catches),
  punting_returns = COALESCE(EXCLUDED.punting_returns, pff_player_gamelogs.punting_returns),
  punting_return_yards = COALESCE(EXCLUDED.punting_return_yards, pff_player_gamelogs.punting_return_yards),
  punting_longest_punt = COALESCE(EXCLUDED.punting_longest_punt, pff_player_gamelogs.punting_longest_punt),
  punting_total_net_yards = COALESCE(EXCLUDED.punting_total_net_yards, pff_player_gamelogs.punting_total_net_yards),
  punting_average_net_yards = COALESCE(EXCLUDED.punting_average_net_yards, pff_player_gamelogs.punting_average_net_yards),
  punting_average_yards_per_attempt = COALESCE(EXCLUDED.punting_average_yards_per_attempt, pff_player_gamelogs.punting_average_yards_per_attempt),
  punting_average_yards_per_return = COALESCE(EXCLUDED.punting_average_yards_per_return, pff_player_gamelogs.punting_average_yards_per_return),
  punting_percentage_returned = COALESCE(EXCLUDED.punting_percentage_returned, pff_player_gamelogs.punting_percentage_returned),
  punting_attempts_with_hangtime = COALESCE(EXCLUDED.punting_attempts_with_hangtime, pff_player_gamelogs.punting_attempts_with_hangtime),
  punting_total_hangtime = COALESCE(EXCLUDED.punting_total_hangtime, pff_player_gamelogs.punting_total_hangtime),
  punting_average_hangtime = COALESCE(EXCLUDED.punting_average_hangtime, pff_player_gamelogs.punting_average_hangtime),
  nfl_team = COALESCE(pff_player_gamelogs.nfl_team, EXCLUDED.nfl_team),
  player_position = COALESCE(pff_player_gamelogs.player_position, EXCLUDED.player_position),
  updated_at = now();
ANALYZE public.pff_player_gamelogs;
